class AvenueGreenWaveEnv:
    CYCLE = 16
    WINDOW = 4
    N_SIGNALS = 3
    MAX_STEPS = 10

    def __init__(self):
        self.rng = None
        self.g = []
        self.steps = 0
        self.done = False

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        max_start = self.CYCLE - self.WINDOW
        self.g = [self.rng.randint(0, max_start) for _ in range(self.N_SIGNALS)]
        self.steps = 0
        self.done = False
        obs = (
            "You are re-timing {n} traffic signals (IDs 0-{nm1}) along an avenue. Each signal "
            "has a hidden GREEN WINDOW of width {w} seconds within its {c}-second cycle "
            "(valid offsets 0-{cm1}), fixed for the whole episode. Goal: submit one offset per "
            "signal that lands inside that signal's true green window.\n"
            "Actions (exactly one per turn):\n"
            "  PROBE <signal_id> <offset>  -> reply is TOO_EARLY, TOO_LATE, or HIT for that "
            "signal's window.\n"
            "  SUBMIT <o0> <o1> ... <o{nm1}>  -> locks in one offset per signal and ends the "
            "episode; you earn {per:.4f} reward for each signal whose offset lands inside its "
            "true window (max 1.0 total).\n"
            "You have {steps} actions total, probes and the submit combined. A malformed "
            "action still costs a turn and earns no reward."
        ).format(
            n=self.N_SIGNALS, nm1=self.N_SIGNALS - 1, w=self.WINDOW, c=self.CYCLE,
            cm1=self.CYCLE - 1, per=1.0 / self.N_SIGNALS, steps=self.MAX_STEPS,
        )
        return obs, {}

    def _malformed(self, msg):
        truncated = self.steps >= self.MAX_STEPS
        self.done = truncated
        return msg, 0.0, False, truncated, {}

    def step(self, action):
        if self.done:
            return "Episode already finished.", 0.0, True, False, {}
        self.steps += 1
        action = (action or "").strip()
        parts = action.split()

        if not parts:
            return self._malformed(
                "Malformed action. Use PROBE <signal_id> <offset> or SUBMIT <o0> ... <o{}>.".format(
                    self.N_SIGNALS - 1
                )
            )

        cmd = parts[0].upper()

        if cmd == "PROBE" and len(parts) == 3:
            sid_str, off_str = parts[1], parts[2]
            if sid_str.isdigit() and off_str.lstrip("-").isdigit():
                sid, off = int(sid_str), int(off_str)
                if 0 <= sid < self.N_SIGNALS and 0 <= off < self.CYCLE:
                    g = self.g[sid]
                    if off < g:
                        result = "TOO_EARLY"
                    elif off >= g + self.WINDOW:
                        result = "TOO_LATE"
                    else:
                        result = "HIT"
                    if self.steps >= self.MAX_STEPS:
                        self.done = True
                        return (
                            f"Signal {sid} @ offset {off}: {result}. Step budget exhausted "
                            "with no SUBMIT - episode truncated, reward 0.",
                            0.0, False, True, {},
                        )
                    return (
                        f"Signal {sid} @ offset {off}: {result}. "
                        f"Steps used: {self.steps}/{self.MAX_STEPS}.",
                        0.0, False, False, {},
                    )
            return self._malformed(
                "Malformed PROBE. Use: PROBE <signal_id 0-{}> <offset 0-{}>.".format(
                    self.N_SIGNALS - 1, self.CYCLE - 1
                )
            )

        if cmd == "SUBMIT" and len(parts) == 1 + self.N_SIGNALS:
            vals = parts[1:]
            if all(v.lstrip("-").isdigit() for v in vals):
                offsets = [int(v) for v in vals]
                if all(0 <= o < self.CYCLE for o in offsets):
                    hits = 0
                    detail = []
                    for sid, off in enumerate(offsets):
                        g = self.g[sid]
                        hit = g <= off < g + self.WINDOW
                        hits += hit
                        detail.append(
                            f"signal {sid}: {'HIT' if hit else 'MISS'} "
                            f"(true window {g}-{g + self.WINDOW - 1})"
                        )
                    reward = hits / self.N_SIGNALS
                    self.done = True
                    obs = (
                        "Final result: " + "; ".join(detail)
                        + f". {hits}/{self.N_SIGNALS} signals timed correctly."
                    )
                    return obs, reward, True, False, {}
            return self._malformed(
                "Malformed SUBMIT. Use: SUBMIT <o0> ... <o{}>, each 0-{}.".format(
                    self.N_SIGNALS - 1, self.CYCLE - 1
                )
            )

        return self._malformed(
            "Malformed action. Use PROBE <signal_id 0-{}> <offset 0-{}> or "
            "SUBMIT <o0> ... <o{}>.".format(self.N_SIGNALS - 1, self.CYCLE - 1, self.N_SIGNALS - 1)
        )

import random


class GemMedianEnv:
    GEM_NAMES = ["A", "B", "C", "D", "E", "F", "G"]

    def __init__(self):
        self.rng = None
        self.weights = {}
        self.step_count = 0
        self.max_steps = 10
        self.done = False
        self.edges = {}
        self.milestone_awarded = False
        self.median_gem = None

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.step_count = 0
        self.done = False
        self.milestone_awarded = False
        values = list(range(1, 8))
        self.rng.shuffle(values)
        self.weights = dict(zip(self.GEM_NAMES, values))
        self.median_gem = next(g for g, w in self.weights.items() if w == 4)
        self.edges = {g: set() for g in self.GEM_NAMES}
        obs = (
            "You are a gem appraiser. Among gems A, B, C, D, E, F, G, exactly one is the "
            "authentic gem: the one whose true weight is exactly in the middle when all "
            "seven are ranked (heavier than exactly three others, lighter than exactly "
            "three others). All seven weights are distinct; no weighing ever balances.\n"
            "Actions:\n"
            "  WEIGH <gem1> <gem2> - place gem1 on the left pan, gem2 on the right pan; "
            "you learn which side is heavier.\n"
            "  SUBMIT <gem> - declare your final answer (ends the episode).\n"
            "You have 10 steps total."
        )
        return obs, {}

    def _direct_heavier(self, g1, g2):
        return self.weights[g1] > self.weights[g2]

    def _reachable(self, start):
        seen = set()
        stack = [start]
        while stack:
            cur = stack.pop()
            for nxt in self.edges[cur]:
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
        return seen

    def _check_milestone(self):
        for g in self.GEM_NAMES:
            lighter = self._reachable(g)
            heavier = set()
            for other in self.GEM_NAMES:
                if other != g and g in self._reachable(other):
                    heavier.add(other)
            if len(lighter) == 3 and len(heavier) == 3:
                return g
        return None

    def step(self, action):
        if self.done:
            return "Episode already finished.", 0.0, True, False, {}

        self.step_count += 1
        parts = action.strip().split()
        reward = 0.0
        terminated = False
        truncated = False
        info = {}

        if (
            len(parts) == 3
            and parts[0].upper() == "WEIGH"
            and parts[1].upper() in self.weights
            and parts[2].upper() in self.weights
            and parts[1].upper() != parts[2].upper()
        ):
            g1, g2 = parts[1].upper(), parts[2].upper()
            if self._direct_heavier(g1, g2):
                self.edges[g1].add(g2)
                obs = f"LEFT_HEAVIER: {g1} is heavier than {g2}."
            else:
                self.edges[g2].add(g1)
                obs = f"RIGHT_HEAVIER: {g2} is heavier than {g1}."
            proven = self._check_milestone()
            if proven is not None and not self.milestone_awarded:
                self.milestone_awarded = True
                reward += 0.3
                obs += " (You now have enough evidence to prove which gem is authentic.)"
        elif len(parts) == 2 and parts[0].upper() == "SUBMIT" and parts[1].upper() in self.weights:
            guess = parts[1].upper()
            terminated = True
            self.done = True
            if guess == self.median_gem:
                reward += 0.7
                obs = f"Correct. {guess} is the authentic gem."
            else:
                obs = f"Incorrect. {guess} is not the authentic gem."
        else:
            obs = "Malformed action. Use 'WEIGH <gem> <gem>' or 'SUBMIT <gem>'."

        if not terminated and self.step_count >= self.max_steps:
            truncated = True
            self.done = True
            obs += " Step limit reached."

        return obs, reward, terminated, truncated, info

import random


class BalanceGemEnv:
    def __init__(self):
        self.n = 8
        self.max_steps = 8

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.fake_index = self.rng.randrange(self.n)
        self.fake_dir = self.rng.choice(['H', 'L'])
        self.steps = 0
        self.done = False
        self.milestones_awarded = 0
        self.candidates = set(
            (i, d) for i in range(self.n) for d in ('H', 'L')
        )
        info = {}
        obs = (
            "You are a gem authenticator. There are 8 gems, indices 0-7. "
            "Exactly one gem is FAKE: it weighs either strictly more (H) or "
            "strictly less (L) than the other 7 identical genuine gems -- "
            "you do not know which gem, nor which direction.\n"
            "Action format:\n"
            "  WEIGH <left indices> | <right indices>\n"
            "    e.g. put three gems on each side, comma-separated, "
            "separated by a single '|'. Groups must be nonempty, equal "
            "size, and disjoint.\n"
            "  Result is one of LEFT_HEAVIER, RIGHT_HEAVIER, BALANCED.\n"
            "When confident, submit your final answer with:\n"
            "  GUESS <index> <H|L>\n"
            "    naming the fake gem's index and whether it is heavier "
            "or lighter.\n"
            "GUESS ends the episode immediately, right or wrong -- you "
            "get exactly one shot at it.\n"
            f"You have {self.max_steps} total actions (weighings plus "
            "the final guess, combined)."
        )
        return obs, info

    def _malformed(self, msg):
        truncated = self.steps >= self.max_steps
        if truncated:
            self.done = True
        return msg, 0.0, False, truncated, {}

    def _parse_indices(self, s):
        s = s.strip()
        if not s:
            raise ValueError("empty group")
        toks = [t.strip() for t in s.split(',')]
        result = []
        seen = set()
        for t in toks:
            core = t[1:] if t.startswith('-') else t
            if not core.isdigit():
                raise ValueError(f"'{t}' is not an integer")
            v = int(t)
            if not (0 <= v < self.n):
                raise ValueError(f"index {v} out of range 0-{self.n - 1}")
            if v in seen:
                raise ValueError(f"duplicate index {v} in same group")
            seen.add(v)
            result.append(v)
        return result

    def _predict(self, i, d, left, right):
        off = 1 if d == 'H' else -1
        l = off if i in left else 0
        r = off if i in right else 0
        if l > r:
            return "LEFT_HEAVIER"
        if l < r:
            return "RIGHT_HEAVIER"
        return "BALANCED"

    def _handle_weigh(self, rest):
        parts = rest.split('|')
        if len(parts) != 2:
            return self._malformed(
                "WEIGH needs exactly one '|' separating two groups, "
                "e.g. left indices, a '|', then right indices."
            )
        try:
            left = self._parse_indices(parts[0])
            right = self._parse_indices(parts[1])
        except ValueError as e:
            return self._malformed(f"Bad indices: {e}")
        if not left or not right:
            return self._malformed("Both groups must be nonempty.")
        if len(left) != len(right):
            return self._malformed("Both groups must be the same size.")
        if set(left) & set(right):
            return self._malformed(
                "Groups must be disjoint -- no gem on both sides."
            )

        outcome = self._predict(self.fake_index, self.fake_dir, left, right)

        new_candidates = {
            c for c in self.candidates
            if self._predict(c[0], c[1], left, right) == outcome
        }
        reward = 0.0
        if len(new_candidates) < len(self.candidates) and self.milestones_awarded < 3:
            reward = 0.15
            self.milestones_awarded += 1
        self.candidates = new_candidates

        truncated = self.steps >= self.max_steps
        if truncated:
            self.done = True
        obs = (
            f"Result: {outcome}. Consistent (gem, direction) possibilities "
            f"remaining: {len(self.candidates)}."
        )
        if truncated:
            obs += " Step limit reached without a guess -- episode over."
        return obs, reward, False, truncated, {}

    def _handle_guess(self, rest):
        tokens = rest.split()
        if len(tokens) != 2:
            return self._malformed(
                "GUESS needs exactly an index and a direction, "
                "e.g. an index then H or L."
            )
        idx_tok, dir_tok = tokens
        core = idx_tok[1:] if idx_tok.startswith('-') else idx_tok
        if not core.isdigit():
            return self._malformed("Index must be an integer 0-7.")
        idx = int(idx_tok)
        if not (0 <= idx < self.n):
            return self._malformed(f"Index must be between 0 and {self.n - 1}.")
        dtok = dir_tok.upper()
        if dtok in ("H", "HEAVIER"):
            d = "H"
        elif dtok in ("L", "LIGHTER"):
            d = "L"
        else:
            return self._malformed("Direction must be H (heavier) or L (lighter).")

        self.done = True
        correct = (idx == self.fake_index and d == self.fake_dir)
        true_word = "heavier" if self.fake_dir == "H" else "lighter"
        if correct:
            reward = 0.55
            obs = f"Correct! Gem {idx} is fake and {true_word}. Episode complete."
        else:
            reward = 0.0
            obs = (
                f"Incorrect guess. The true fake was gem {self.fake_index} "
                f"({true_word}). Episode complete."
            )
        return obs, reward, True, False, {}

    def step(self, action):
        if self.done:
            return "Episode already finished.", 0.0, True, False, {}
        self.steps += 1
        text = (action or "").strip()
        upper = text.upper()
        if upper.startswith("WEIGH"):
            return self._handle_weigh(text[5:].strip())
        elif upper.startswith("GUESS"):
            return self._handle_guess(text[5:].strip())
        else:
            truncated = self.steps >= self.max_steps
            if truncated:
                self.done = True
            return (
                "Malformed action. Use 'WEIGH a,b,c | d,e,f' or "
                "'GUESS <index> <H|L>'.",
                0.0, False, truncated, {}
            )

import random


class RhythmProgressionEnv:
    N = 16
    MAX_STEPS = 10

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.step_count = 0
        self.terminated = False
        self.count_rewarded = False
        self.submitted = False

        k1 = self.rng.choice([3, 4, 5])
        d = self.rng.choice([1, 2])
        self.k_seq = [k1 + i * d for i in range(5)]  # bars 1..5
        self.target_k = self.k_seq[4]
        self.target_pattern = self._pattern(self.target_k)

        bars_text = []
        for i in range(3):
            bars_text.append(
                f"Bar {i + 1} ({self.k_seq[i]} hits): {self._pattern(self.k_seq[i])}"
            )

        obs = (
            "GROOVE RECONSTRUCTION. Each bar has 16 sixteenth-note steps (positions 0-15), "
            "shown left to right as 'X' (hit) or '.' (rest). The hit COUNT rises by a fixed "
            "amount from bar to bar. Within any bar, the hits are always spread as evenly as "
            "possible across the 16 steps by one fixed, undisclosed rule that depends only on "
            "the hit count.\n\n"
            + "\n".join(bars_text)
            + "\n\nGoal: reconstruct Bar 5 exactly, as a 16-character string of X/. .\n\n"
            "Actions (send exactly one per turn):\n"
            "  PROBE <k> <pos>   - ask whether step <pos> (integer 0-15) is a hit in the "
            "16-step pattern for hit-count <k> (integer 1-16), under the same fixed rule.\n"
            "  COUNT <k>         - declare your answer for how many hits Bar 5 contains.\n"
            "  SUBMIT <pattern>  - submit your final 16-character X/. guess for Bar 5. This "
            "ends the episode.\n"
            f"You have {self.MAX_STEPS} steps total; PROBE, COUNT, and SUBMIT each use one "
            "step. SUBMIT may only be used once."
        )
        return obs, {}

    def _pattern(self, k):
        hits = set((i * self.N) // k for i in range(k))
        return "".join("X" if i in hits else "." for i in range(self.N))

    def step(self, action):
        if self.terminated:
            return "Episode already over.", 0.0, True, False, {}

        self.step_count += 1
        text = (action or "").strip()
        parts = text.split()
        reward = 0.0
        obs = ""

        if not parts:
            obs = "Empty action. Use PROBE <k> <pos>, COUNT <k>, or SUBMIT <pattern>."
        else:
            cmd = parts[0].upper()

            if cmd == "PROBE" and len(parts) == 3:
                try:
                    k = int(parts[1])
                    pos = int(parts[2])
                except ValueError:
                    k = pos = None
                if k is None or not (1 <= k <= 16) or not (0 <= pos <= 15):
                    obs = "Malformed PROBE. Use: PROBE <k 1-16> <pos 0-15>."
                else:
                    pat = self._pattern(k)
                    verdict = "HIT" if pat[pos] == "X" else "REST"
                    obs = f"PROBE k={k} pos={pos} -> {verdict}"

            elif cmd == "COUNT" and len(parts) == 2:
                try:
                    k = int(parts[1])
                except ValueError:
                    k = None
                if k is None or not (1 <= k <= 60):
                    obs = "Malformed COUNT. Use: COUNT <integer hit count>."
                elif k == self.target_k:
                    if not self.count_rewarded:
                        reward = 0.3
                        self.count_rewarded = True
                        obs = "COUNT correct. Bar 5's hit count is confirmed."
                    else:
                        obs = "COUNT correct (already rewarded once)."
                else:
                    obs = "COUNT incorrect for Bar 5's hit count."

            elif cmd == "SUBMIT" and len(parts) == 2:
                guess = parts[1].upper()
                if len(guess) != self.N or any(c not in "X." for c in guess):
                    obs = "Malformed SUBMIT. Send exactly 16 characters made of X and . only."
                else:
                    self.submitted = True
                    self.terminated = True
                    matches = sum(1 for a, b in zip(guess, self.target_pattern) if a == b)
                    if guess == self.target_pattern:
                        reward = 0.7
                        obs = (
                            f"SUBMIT exact match! Bar 5 was: {self.target_pattern}. "
                            "Episode complete."
                        )
                    else:
                        reward = 0.7 * (matches / self.N)
                        obs = (
                            f"SUBMIT incorrect. {matches}/16 positions matched. "
                            f"Bar 5 was: {self.target_pattern}. Episode complete."
                        )
            else:
                obs = (
                    "Unrecognized action. Use PROBE <k> <pos>, COUNT <k>, or "
                    "SUBMIT <16-char X/. pattern>."
                )

        truncated = False
        if not self.terminated and self.step_count >= self.MAX_STEPS:
            truncated = True
            obs += " Step limit reached without a submission."

        info = {
            "steps_remaining": max(0, self.MAX_STEPS - self.step_count),
        }
        return obs, reward, self.terminated, truncated, info

